import java.util.*;

class Solution {
    public boolean isSorted(int[] nums) {
        int previous = nums[0];

        for (int i = 1; i < nums.length; i++) {
            if (nums[i] < previous) {
                return false;
            }
            previous = nums[i];
        }

        return true;
    }
}

import java.util.*;
public class Main {
    static class Node {
        int data;
        Node next;
        Node(int data) { this.data = data; }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Node[] nodes = new Node[n];
        for (int i = 0; i < n; i++) {
            nodes[i] = new Node(sc.nextInt());
        }
        int pos = sc.nextInt();
        Node head = n == 0 ? null : nodes[0];
        for (int i = 0; i + 1 < n; i++) {
            nodes[i].next = nodes[i + 1];
        }
        if (n > 0 && pos > 0) {
            nodes[n - 1].next = nodes[pos - 1];
        }
        Node slow = head;
        Node fast = head;
        boolean cycle = false;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow != null && fast != null && slow.data == fast.data) {
                cycle = true;
                break;
            }
        }
        System.out.println(cycle ? "Cycle" : "No Cycle");
        sc.close();
    }
}

import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        int[] values = new int[n];
        for (int i = 0; i < n; i++) {
            values[i] = sc.nextInt();
        }
        Deque<Integer> deque = new ArrayDeque<>();
        List<Integer> answer = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            while (!deque.isEmpty() && values[deque.peekLast()] <= values[i]) {
                deque.pollLast();
            }
            deque.offerLast(i);
            if (i >= k - 1) {
                answer.add(values[deque.peekFirst()]);
            }
        }
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < answer.size(); i++) {
            if (i > 0) out.append(' ');
            out.append(answer.get(i));
        }
        System.out.println(out);
        sc.close();
    }
}

